import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./optimizevideo.css";

const OptimizeVideo = () => {
    const location = useLocation();
    const [videoPath, setVideoPath] = useState("");
    const [message, setMessage] = useState("");
    const [processingDetails, setProcessingDetails] = useState({});

    useEffect(() => {
        if (location.state) {
            const { videoURL, response } = location.state;
            console.log("Received state:", location.state);
            console.log("Processing results:", response?.results);

            const results = response?.results || {};
            setProcessingDetails(results);

            // Check for audio processing path first
            const audioPath = results?.audio_processing?.enhanced_video_path;
            const videoPath = results?.video_upscaling?.output_path;

            // Extract filename from the full path
            const getMediaUrl = (path) => {
                if (!path) return null;
                const filename = path.split('\\').pop();
                return `http://127.0.0.1:8000/media/${filename}`;
            };

            // Prefer audio processed path if it exists, otherwise use video optimized path
            const finalPath = getMediaUrl(audioPath) || getMediaUrl(videoPath);

            if (finalPath) {
                console.log("Setting video path:", finalPath);
                setVideoPath(finalPath);

                // Set appropriate message based on processing done
                const processTypes = [];
                if (audioPath) processTypes.push("audio enhancement");
                if (videoPath) processTypes.push("video quality optimization");

                setMessage(`Video processing complete with ${processTypes.join(" and ")}.`);
            } else {
                setMessage("No processed video available.");
            }
        }
    }, [location.state]);

    const handlePreview = () => {
        const videoElement = document.querySelector('.optimized-video');
        if (videoElement) {
            videoElement.play();
        } else {
            alert("No video available for preview.");
        }
    };

    const handleDownload = () => {
        if (videoPath) {
            const link = document.createElement("a");
            link.href = videoPath;
            // Extract filename from the path or use default
            const filename = videoPath.split('/').pop() || "optimized-video.mp4";
            link.download = filename;
            link.click();
        } else {
            alert("No video available for download.");
        }
    };

    return (
        <div className="optimized-video-page">
            <header className="page-header">
                <h1>Optimized Video Output</h1>
                <p>{message}</p>
            </header>

            <div className="video-output">
                {videoPath ? (
                    <>
                        <video
                            className="optimized-video"
                            controls
                            src={videoPath}
                            alt="Optimized Video Output"
                        >
                            Your browser does not support the video tag.
                        </video>
                        <div className="processing-details">
                            {processingDetails.video_upscaling && (
                                <p>Video quality has been optimized</p>
                            )}
                            {processingDetails.audio_processing && (
                                <p>Audio has been enhanced</p>
                            )}
                        </div>
                    </>
                ) : (
                    <p>No optimized video available.</p>
                )}

                <div className="action-buttons">
                    <button
                        className="preview-button"
                        onClick={handlePreview}
                        disabled={!videoPath}
                    >
                        Preview
                    </button>
                    <button
                        className="download-button"
                        onClick={handleDownload}
                        disabled={!videoPath}
                    >
                        Download
                    </button>
                </div>
            </div>
        </div>
    );
};

export default OptimizeVideo;
